const items = $input.all();
const allowed = new Set(['jpg', 'jpeg', 'png']);
return items.filter((item) => {
  const name = String(item.json?.name || '').toLowerCase();
  const extension = name.includes('.') ? name.split('.').pop() : '';
  return allowed.has(extension);
});

const binary = $input.first().binary?.data || {};
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const payload = { model: $env.DEEPSEEK_MODEL || 'deepseek-flash', messages: [{ role: 'user', content: [{ type: 'text', text: 'Read this invoice image carefully. Return the complete visible OCR text only. Do not summarize and do not invent missing values.' }, { type: 'image_url', image_url: { url: 'data:' + (binary.mimeType || 'image/png') + ';base64,' + buffer.toString('base64'), detail: 'original' } }] }] };
return [{ json: { request_body: payload } }];

const input = $input.first().json || {};
const raw = input.choices?.[0]?.message?.content || input.text || '';
const source = $items('Google Drive Trigger')[0]?.json || {};
let parsed = {};
try {
  let candidate = String(raw).trim();
  if (candidate.startsWith('```')) candidate = candidate.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  parsed = JSON.parse(candidate);
} catch (error) { parsed = {}; }
const scores = parsed.confidence_scores || {};
const fields = ['vendor', 'invoice_date', 'invoice_number', 'amount'];
const present = fields.filter(field => parsed[field] !== undefined && parsed[field] !== null && String(parsed[field]).trim() !== '');
const completeness = present.length / fields.length;
const overall = Number(scores.overall);
const confidence = Number.isFinite(overall) ? Math.max(0, Math.min(1, overall)) : completeness;
const amountText = String(parsed.amount ?? '').replace(/[^0-9.,-]/g, '').replace(/\.(?=.*\.)/g, '').replace(',', '.');
const amount = Number(amountText) || 0;
const fileId = source.id || '';
const visionResponse = $items('AI Vision OCR')[0]?.json || {};
const visionContent = visionResponse.choices?.[0]?.message?.content || visionResponse.text || '';
const ocrText = Array.isArray(visionContent) ? visionContent.map(part => part.text || '').join('\n') : String(visionContent);
return [{ json: { vendor: parsed.vendor || '', invoice_date: parsed.invoice_date || '', invoice_number: parsed.invoice_number || '', amount, confidence_scores: { vendor: Number(scores.vendor) || 0, invoice_date: Number(scores.invoice_date) || 0, invoice_number: Number(scores.invoice_number) || 0, amount: Number(scores.amount) || 0, overall: confidence }, overall_confidence: confidence, source: 'Drive', drive_file_id: fileId, drive_file_link: fileId ? 'https://drive.google.com/file/d/' + fileId + '/view' : '', ocr_text: ocrText, extraction_error: present.length === 0 ? 'DeepSeek did not return valid invoice fields' : '' } }];

const invoice = $items('Parse DeepSeek Response')[0]?.json || {};
const existingRows = $input.all().map(item => item.json).filter(row => row && row.invoice_id);
const key = row => [row.vendor, row.invoice_number, row.invoice_date, row.amount].map(value => String(value ?? '').trim().toLowerCase()).join('|');
const newKey = key(invoice);
const matchedIndex = existingRows.findIndex(row => key(row) === newKey && newKey !== '|||');
return [{ json: { ...invoice, is_duplicate: matchedIndex >= 0, matched_row_index: matchedIndex, status: matchedIndex >= 0 ? 'Duplicate' : 'Pending Approval' } }];

const inv = $input.first().json;
const now = new Date().toISOString();
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; const v = c === 'x' ? r : (r & 0x3 | 0x8); return v.toString(16); });
return [{ json: { invoice_id: uuid, received_at: now, vendor: inv.vendor || '', invoice_date: inv.invoice_date || '', invoice_number: inv.invoice_number || '', amount: inv.amount || 0, status: 'Pending Approval', confidence: inv.overall_confidence || 0, drive_file_id: inv.drive_file_id || '', drive_file_link: inv.drive_file_link || '', source: 'Drive', approved_at: '', approved_by: '', rejected_at: '', reject_reason: '', reminder_count: 0, last_reminder_at: '', created_at: now, updated_at: now } }];

const inv = $input.first().json;
const now = new Date().toISOString();
return [{ json: { invoice_id: 'DUPLICATE-' + Date.now(), received_at: now, vendor: inv.vendor || '', invoice_date: inv.invoice_date || '', invoice_number: inv.invoice_number || '', amount: inv.amount || 0, status: 'Duplicate', confidence: inv.overall_confidence || 0, drive_file_id: inv.drive_file_id || '', drive_file_link: inv.drive_file_link || '', source: 'Drive', approved_at: '', approved_by: '', rejected_at: '', reject_reason: 'Duplicate of existing invoice (row ' + (inv.matched_row_index + 1) + ')', reminder_count: 0, last_reminder_at: '', created_at: now, updated_at: now } }];

const inv = $input.first().json;
const amount = 'Rp ' + (Number(inv.amount) || 0).toLocaleString('id-ID');
const confidence = Math.round((Number(inv.confidence) || 0) * 100);
const message = [
  'INVOICE BARU MASUK',
  '',
  'Vendor: ' + (inv.vendor || '-'),
  'Tanggal: ' + (inv.invoice_date || '-'),
  'No. Invoice: ' + (inv.invoice_number || '-'),
  'Nominal: ' + amount,
  'Confidence: ' + confidence + '%',
  'Status: Pending Approval'
].join('\n');
return [{ json: { chatId: String($env.TELEGRAM_OWNER_CHAT_ID || ''), text: message, invoice_id: inv.invoice_id } }];

const inv = $input.first().json;
const now = new Date().toISOString();
return [{ json: { invoice_id: 'LOWCONF-' + Date.now(), received_at: now, vendor: inv.vendor || 'UNKNOWN', invoice_date: inv.invoice_date || '', invoice_number: inv.invoice_number || '', amount: inv.amount || 0, status: 'Low Confidence', confidence: inv.overall_confidence || 0, drive_file_id: inv.drive_file_id || '', drive_file_link: inv.drive_file_link || '', source: 'Drive', approved_at: '', approved_by: '', rejected_at: '', reject_reason: inv.extraction_error || 'Extraction confidence below 85% -- manual review required', reminder_count: 0, last_reminder_at: '', created_at: now, updated_at: now } }];

